import{_ as d,o as r,c as a,a3 as e}from"./chunks/framework.bvEHUNtb.js";const u=JSON.parse('{"title":"梅花易数·系统学习计划","description":"以《梅花易数》原典为底本，按卷次、阶段与节次循序学习。","frontmatter":{"title":"梅花易数·系统学习计划","description":"以《梅花易数》原典为底本，按卷次、阶段与节次循序学习。","layout":"page","pageClass":"dao-doc-page dao-directory-page meihua-study-plan","aside":false,"outline":false},"headers":[],"relativePath":"yijing/meihua-yishu/index.md","filePath":"yijing/meihua-yishu/index.md","lastUpdated":1786982540000}'),i={name:"yijing/meihua-yishu/index.md"};function l(h,t,o,n,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<div class="dao-directory"><div class="dao-directory__hero"><p class="dao-directory__eyebrow">易经学习 · 原典专题</p><h1>梅花易数·系统学习计划</h1><p class="dao-directory__lede">底本：占卜／梅花易数·宋·邵雍（附清·黄宗羲序）<br>制定日期：2026 年 7 月 27 日</p></div><div class="dao-directory-card dao-directory-card--preface"><span class="dao-directory-card__index">序</span><div><h2>黄宗羲序</h2><p>作为背景、人物与起源入口，原稿补齐后按统一学习格式展开。</p><a href="/yijing/meihua-yishu/preface">进入序页</a></div></div><div class="dao-directory__grid dao-directory__grid--three"><article class="dao-directory-card dao-directory-card--lead"><span class="dao-directory-card__index">一</span><h2>象数易理篇</h2><p>建立数理、起卦与八卦类象的共同语言。</p><a href="/yijing/meihua-yishu/xiang-shu-li/">进入第一阶段</a></article><article class="dao-directory-card dao-directory-card--accent"><span class="dao-directory-card__index">二</span><h2>体用生克篇</h2><p>通过案例掌握体用、生克、三要与十应。</p><a href="/yijing/meihua-yishu/ti-yong-sheng-ke/">进入第二阶段</a></article><article class="dao-directory-card"><span class="dao-directory-card__index">三</span><h2>断占总诀篇</h2><p>综合象数、体用与克应，回到完整断占结构。</p><a href="/yijing/meihua-yishu/duan-zhan-zong-jue/">进入第三阶段</a></article></div></div><h2 id="一、文本总览" tabindex="-1">一、文本总览 <a class="header-anchor" href="#一、文本总览" aria-label="Permalink to &quot;一、文本总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>内容</th><th>性质</th></tr></thead><tbody><tr><td>序</td><td>黄宗羲序（清）</td><td>背景·人物·起源</td></tr><tr><td>卷一·象数易理篇之一</td><td>周易卦数·五行·起卦法·占法</td><td>基础数理</td></tr><tr><td>卷一·象数易理篇之二</td><td>物卦起例·经典案例（观梅·牡丹等）</td><td>案例入门</td></tr><tr><td>卷一·象数易理篇之三</td><td>八卦类象·万物属类（详表）</td><td>象意词典</td></tr><tr><td>卷二·体用生克篇之一</td><td>心易玄机·占卜总诀·体用总诀</td><td>核心框架</td></tr><tr><td>卷二·体用生克篇之二</td><td>天时·人事·家宅等十八占例</td><td>分类断法</td></tr><tr><td>卷二·体用生克篇之三</td><td>三要灵应篇</td><td>耳目心法</td></tr><tr><td>卷二·体用生克篇之四</td><td>十应奥论·体用论·衰旺·动静</td><td>进阶理论</td></tr><tr><td>卷二·体用生克篇之五</td><td>观物洞玄歌·屋宅器物占</td><td>观物应用</td></tr><tr><td>卷三·断占总诀篇之一</td><td>八卦方位·变卦式·体用诸诀</td><td>综合断法</td></tr><tr><td>卷三·断占总诀篇之二</td><td>万物赋·饮食篇·诸事响应歌</td><td>赋文总结</td></tr><tr><td>卷三·断占总诀篇之三</td><td>诸卦反对·占物类例·观物诸诀</td><td>观物精要</td></tr><tr><td>卷三·断占总诀篇之四</td><td>占卜十应诀·论事十大应·卦应</td><td>十应完整</td></tr></tbody></table><h2 id="二、学习阶段规划" tabindex="-1">二、学习阶段规划 <a class="header-anchor" href="#二、学习阶段规划" aria-label="Permalink to &quot;二、学习阶段规划&quot;">​</a></h2><h3 id="🔷-第一阶段·地基-卷一之一" tabindex="-1">🔷 第一阶段·地基（卷一之一） <a class="header-anchor" href="#🔷-第一阶段·地基-卷一之一" aria-label="Permalink to &quot;🔷 第一阶段·地基（卷一之一）&quot;">​</a></h3><p><strong>目标：</strong> 搞清楚梅花易数的数理基础，能看懂起卦过程。</p><table tabindex="0"><thead><tr><th>节次</th><th>内容</th></tr></thead><tbody><tr><td>1-1</td><td>序：黄宗羲序——邵雍其人与观梅数起源</td></tr><tr><td>1-2</td><td>周易卦数·五行生克·八宫五行</td></tr><tr><td>1-3</td><td>卦气旺衰·十天干·十二地支</td></tr><tr><td>1-4</td><td>八卦象例·占法·玩法</td></tr><tr><td>1-5</td><td>卦以八除·爻以六除·互卦起例</td></tr><tr><td>1-6</td><td>年月日时起卦·物数·声音·字占</td></tr><tr><td>1-7</td><td>丈尺·尺寸·为人占·自己占·动静物占</td></tr></tbody></table><h3 id="🔷-第二阶段·框架-卷一之二-卷二之一" tabindex="-1">🔷 第二阶段·框架（卷一之二 + 卷二之一） <a class="header-anchor" href="#🔷-第二阶段·框架-卷一之二-卷二之一" aria-label="Permalink to &quot;🔷 第二阶段·框架（卷一之二 + 卷二之一）&quot;">​</a></h3><p><strong>目标：</strong> 通过经典案例理解起卦逻辑，掌握体用核心。</p><table tabindex="0"><thead><tr><th>节次</th><th>内容</th></tr></thead><tbody><tr><td>2-1</td><td>物卦起例（端法后天起卦）</td></tr><tr><td>2-2</td><td>八卦万物属类（上卦用表）</td></tr><tr><td>2-3</td><td>观梅占·牡丹占（完整复盘）</td></tr><tr><td>2-4</td><td>邻夜叩门·今日动静·西林寺额（案例组）</td></tr><tr><td>2-5</td><td>老人忧色·少年喜色·牛鸣·鸡鸣（案例组）</td></tr><tr><td>2-6</td><td>枯枝坠地·风觉·鸟占·听声·形物·验色</td></tr><tr><td>2-7</td><td>心易占卜玄机·占卜总诀·论理诀</td></tr><tr><td>2-8</td><td>先天后天论·卦断遗论</td></tr><tr><td>2-9</td><td>八卦心易体用诀·体用总诀</td></tr></tbody></table><h3 id="🔷-第三阶段·应用-卷二之二-卷二之三·四" tabindex="-1">🔷 第三阶段·应用（卷二之二 + 卷二之三·四） <a class="header-anchor" href="#🔷-第三阶段·应用-卷二之二-卷二之三·四" aria-label="Permalink to &quot;🔷 第三阶段·应用（卷二之二 + 卷二之三·四）&quot;">​</a></h3><p><strong>目标：</strong> 掌握各类事项的断法，理解三要十应。</p><table tabindex="0"><thead><tr><th>节次</th><th>内容</th></tr></thead><tbody><tr><td>3-1</td><td>天时占·人事占·家宅占·屋舍占</td></tr><tr><td>3-2</td><td>婚姻占·生产占·饮食占·求谋占</td></tr><tr><td>3-3</td><td>求名占·求财占·交易占·出行占</td></tr><tr><td>3-4</td><td>行人占·谒见占·失物占·疾病占</td></tr><tr><td>3-5</td><td>官讼占·坟墓占</td></tr><tr><td>3-6</td><td>三要灵应篇序·三要灵应篇（全）</td></tr><tr><td>3-7</td><td>十应奥论·十应目论</td></tr><tr><td>3-8</td><td>十一类复明（天时·地理·人事·时令·方卦·动静物·言语·声音·五色·写字）</td></tr><tr><td>3-9</td><td>遗论·体用·体用论·衰旺论·内外论·动静·向背·静占</td></tr></tbody></table><h3 id="🔷-第四阶段·融通-卷二之五-卷三全" tabindex="-1">🔷 第四阶段·融通（卷二之五 + 卷三全） <a class="header-anchor" href="#🔷-第四阶段·融通-卷二之五-卷三全" aria-label="Permalink to &quot;🔷 第四阶段·融通（卷二之五 + 卷三全）&quot;">​</a></h3><p><strong>目标：</strong> 综合运用，贯通全书。</p><table tabindex="0"><thead><tr><th>节次</th><th>内容</th></tr></thead><tbody><tr><td>4-1</td><td>观物洞玄歌·起卦加数例·屋宅占诀·器物占</td></tr><tr><td>4-2</td><td>八卦方位图·观梅数诀序·八卦定阴阳次序</td></tr><tr><td>4-3</td><td>变卦式八则（含案例详解）</td></tr><tr><td>4-4</td><td>占卦诀·体用互变之诀·生克之诀·衰旺之诀·动静之诀</td></tr><tr><td>4-5</td><td>占卜坐端之诀·克应之诀</td></tr><tr><td>4-6</td><td>万物赋·饮食篇</td></tr><tr><td>4-7</td><td>观物玄妙歌诀·诸事响应歌</td></tr><tr><td>4-8</td><td>诸卦反对性情·占物类例·物数为体诀</td></tr><tr><td>4-9</td><td>观物看变爻·克应法·趣时诀·用易例·万物戏验</td></tr><tr><td>4-10</td><td>占卜十应诀·论事十大应·卦应</td></tr><tr><td>4-11</td><td>全书回顾与贯通</td></tr></tbody></table><h2 id="三、每节固定学习格式" tabindex="-1">三、每节固定学习格式 <a class="header-anchor" href="#三、每节固定学习格式" aria-label="Permalink to &quot;三、每节固定学习格式&quot;">​</a></h2><p>每一节按以下结构展开，保持一致：</p><ol><li>📜 原文：照录原文，保持原貌</li><li>🔤 注音与字词：难字注音，关键词释义</li><li>📖 白话译文：逐句今译，不意译，保留原意</li><li>🧭 义理解析：核心概念、逻辑结构、与《易经》本经对照</li><li>🔍 案例复盘：有案例时还原起卦过程，梳理断卦逻辑</li><li>🌀 象的感悟：感受卦象背后的意象与气息</li><li>📌 小结：提炼关键词、规律并与前文呼应</li><li>❓ 存疑：标记不确定处，留待后续解答</li></ol><h2 id="四、学习约定原则" tabindex="-1">四、学习约定原则 <a class="header-anchor" href="#四、学习约定原则" aria-label="Permalink to &quot;四、学习约定原则&quot;">​</a></h2><h3 id="📐-节奏约定" tabindex="-1">📐 节奏约定 <a class="header-anchor" href="#📐-节奏约定" aria-label="Permalink to &quot;📐 节奏约定&quot;">​</a></h3><ul><li>按节推进，不跳跃，不因后面内容而提前引用。</li><li>每节学完，昇哥确认后再进入下一节。</li><li>如某节内容较长，可拆分为上下两次。</li></ul><h3 id="🎯-态度约定" tabindex="-1">🎯 态度约定 <a class="header-anchor" href="#🎯-态度约定" aria-label="Permalink to &quot;🎯 态度约定&quot;">​</a></h3><ul><li>存疑处标记，不强行解释，积累到一定量后集中讨论。</li><li>与《周易》本经互参，注意原典出处。</li><li>理论联系案例，每个理论尽量找到对应案例印证。</li><li>黄宗羲序中的故事作为背景理解，不作为正文解读。</li></ul><h3 id="🌀-象的约定-核心原则" tabindex="-1">🌀 象的约定（核心原则） <a class="header-anchor" href="#🌀-象的约定-核心原则" aria-label="Permalink to &quot;🌀 象的约定（核心原则）&quot;">​</a></h3><ul><li>以原文为主，以象为魂。</li><li>梅花易数的精髓在于“观象”，而非“执文”：文字是地图，象才是山川。</li><li>每节固定保留“象的感悟”，尝试用直觉和意象感受卦，而非仅做文字注解。</li><li>遇到卦象时先问：这个象像什么？让你想到什么？再看文字解释。</li><li>不以记住规则为目标，以感受到象为目标；万物皆有象，象皆通于易。</li></ul><h3 id="📝-记录与互参" tabindex="-1">📝 记录与互参 <a class="header-anchor" href="#📝-记录与互参" aria-label="Permalink to &quot;📝 记录与互参&quot;">​</a></h3><ul><li>关键概念首次出现时建立词条，疑问用 ❓ 标记，积累后集中解答。</li><li>每个阶段结束后做一次小结归纳。</li><li>案例中的起卦数字完整还原计算过程，不跳步骤。</li><li>梅花易数引用的《易》辞，回溯到对应卦爻辞原文。</li><li>涉及五行、天干地支，结合卷一基础表格理解；同一概念跨篇章前后对照。</li></ul><h2 id="五、词条库" tabindex="-1">五、词条库 <a class="header-anchor" href="#五、词条库" aria-label="Permalink to &quot;五、词条库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词条</th><th>首次出现</th><th>简释</th></tr></thead><tbody><tr><td>先天之数</td><td>卷一·象数易理篇之二</td><td>未得卦先得数，以数起卦</td></tr><tr><td>后天之数</td><td>卷一·象数易理篇之二</td><td>未得数先得卦，以卦起数</td></tr><tr><td>体卦</td><td>卷二·体用生克篇之一</td><td>占卜中代表己方／主体的卦</td></tr><tr><td>用卦</td><td>卷二·体用生克篇之一</td><td>占卜中代表事情／对方的卦</td></tr><tr><td>互卦</td><td>卷一·象数易理篇之一</td><td>去初爻与上爻，中间四爻组成的两卦</td></tr><tr><td>变卦</td><td>卷一·象数易理篇之一</td><td>动爻变化后形成的新卦</td></tr><tr><td>克应</td><td>卷二·体用生克篇之一</td><td>占卜时外部环境对卦象的印证</td></tr><tr><td>三要</td><td>卷二·体用生克篇之三</td><td>耳、目、心三者之要</td></tr><tr><td>十应</td><td>卷二·体用生克篇之四</td><td>正、互、变、方、日、刻、外、天时、地理、人事</td></tr></tbody></table><h2 id="六、进度记录" tabindex="-1">六、进度记录 <a class="header-anchor" href="#六、进度记录" aria-label="Permalink to &quot;六、进度记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>节次</th><th>状态</th><th>备注</th></tr></thead><tbody><tr><td>第一阶段</td><td>1-1 序</td><td>🟡 进行中</td><td>原稿待补</td></tr><tr><td>第一阶段</td><td>1-2 卦数五行</td><td>⬜ 待学</td><td></td></tr><tr><td>第一阶段</td><td>1-3 卦气旺衰</td><td>⬜ 待学</td><td></td></tr><tr><td>第一阶段</td><td>1-4 八卦象例</td><td>⬜ 待学</td><td></td></tr><tr><td>第一阶段</td><td>1-5 起卦法</td><td>⬜ 待学</td><td></td></tr><tr><td>第一阶段</td><td>1-6 年月日时起卦</td><td>⬜ 待学</td><td></td></tr><tr><td>第一阶段</td><td>1-7 为人占·动静物</td><td>⬜ 待学</td><td></td></tr></tbody></table><blockquote><p>⬜ 待学　🟡 进行中　✅ 已完成　❓ 存疑待解</p></blockquote><p>本计划随学习进展动态调整。核心原则：以原文为主，多感悟象，勿执着文字。</p>',34)])])}const p=d(i,[["render",l]]);export{u as __pageData,p as default};
